from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            seen.add((r, c))
            q = deque([(r, c)])
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x, grid[y][x]))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                grid[ny][nx] != bg and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            q.append((ny, nx))
            components.append(comp)

    if not components:
        return [row[:] for row in grid]

    pattern = max(components, key=len)
    pattern_cells = {(r, c) for r, c, _ in pattern}
    minr = min(r for r, _, _ in pattern)
    maxr = max(r for r, _, _ in pattern)
    minc = min(c for _, c, _ in pattern)
    maxc = max(c for _, c, _ in pattern)
    cr, cc = (minr + maxr) // 2, (minc + maxc) // 2
    offsets = [(r - cr, c - cc, color) for r, c, color in pattern]

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and (r, c) not in pattern_cells:
                for dr, dc, color in offsets:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        out[nr][nc] = color
    return out
